'use strict';

/* 广播电台订阅源 v1.6
 * 导入的播放列表解析后，「每个电台频道」直接作为一本书出现在发现/搜索页。
 * 点开频道 → 目录=1个「收听」章节 → 直接播放。
 * 支持 单流 / HLS / m3u·pls 播放列表；content-type 探测、自定义请求头、频道可播标记。
 */
const STATIONS_KEY='radio.stations.v1';
const DEFAULT_STATIONS=[];
function text(v){ return v===undefined||v===null?'':String(v); }
function hdrs(h){ return (h&&typeof h==='object')?h:{}; }
function normalizeStation(s){ const url=text(s&&s.url).trim(); if(!url) return null;
  return { id:text(s&&s.id)||url, name:text(s&&s.name)||url, url, group:text(s&&s.group)||'', headers:hdrs(s&&s.headers), content:text(s&&s.content)||'' }; }
function getStations(){ const saved=reader.storage.get(STATIONS_KEY);
  const list=Array.isArray(saved)&&saved.length>0?saved:DEFAULT_STATIONS; return list.map(normalizeStation).filter(Boolean); }
async function getStationsAsync(){ const saved=await Promise.resolve(reader.storage.get(STATIONS_KEY));
  const list=Array.isArray(saved)&&saved.length>0?saved:DEFAULT_STATIONS; return list.map(normalizeStation).filter(Boolean); }
function contentTypeOf(res){ const h=(res&&res.headers)||{}; const k=Object.keys(h).find(k=>k.toLowerCase()==='content-type'); return k?String(h[k]).toLowerCase():''; }
function isAudioSource(ct,url){ if(/apple-mpegurl|x-mpegurl|mpegurl|audio\//i.test(ct)) return true;
  if(/\.(?:m3u8|mp3|aac|m4a|ogg|opus|flac|wav)(?:\?|$)/i.test(text(url))) return true;
  return /audio|mpeg|aac|mp3|m4a|ogg|opus|flac|wav/i.test(ct); }
async function probeStream(url,headers,timeoutMs){ try{
  const r=await Promise.resolve(reader.http.fetch({url,method:'GET',headers:Object.assign({'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Range':'bytes=0-1024'},headers||{}),timeoutMs:timeoutMs||6000}));
  const st=Number((r&&r.status)||0); if(st<200||st>=400) return {ok:false,code:st,msg:'HTTP '+st};
  const ct=contentTypeOf(r);
  if(/text\/html|application\/json/i.test(ct)) return {ok:false,code:st,msg:'返回网页/JSON（可能失效）'};
  return {ok:isAudioSource(ct,url),code:st,msg:isAudioSource(ct,url)?'':'内容不是音频流'};
}catch(e){ return {ok:false,code:0,msg:String(e&&e.message||e).slice(0,40)}; } }
function parsePlaylist(body,base,depth){ if(depth>3) return [];
  const b=text(body).replace(/^\uFEFF/,'').trim(); const out=[]; const seen=new Set();
  const add=(u,t)=>{ let v=text(u).trim(); if(!v) return;
    if(/^\s*file\d*\s*=/i.test(v)) v=v.replace(/^file\d*\s*=\s*/i,'');
    if(/^https?:|^\/\//i.test(v)){ if(v.startsWith('//')){ const s=(base.match(/^https?:/i)||['https:'])[0]; v=s+v; }
      if(base&&v.startsWith('/')){ const o=(base.match(/^https?:\/\/[^/]+/i)||[''])[0]; v=o+v; }
      if(!seen.has(v)){ seen.add(v); out.push({title:text(t)||('频道 '+(out.length+1)),url:v}); } } };
  if(/^\s*\[playlist\]/i.test(b)){ const files=[]; const titles={};
    b.split(/\r?\n/).forEach(line=>{ const m=line.trim().match(/^File(\d*)\s*=\s*(.+)$/i); if(m) files[Number(m[1])||1]=m[2].trim();
      const mt=line.trim().match(/^Title(\d*)\s*=\s*(.+)$/i); if(mt) titles[Number(mt[1])||1]=mt[2].trim(); });
    files.forEach((u,i)=>add(u,titles[i]||'')); }
  else if(/^#EXTM3U|#EXTINF/i.test(b)){ let title=''; b.split(/\r?\n/).forEach(line=>{ const l=line.trim();
      if(/^#EXTINF/i.test(l)){ const t=l.replace(/^#EXTINF[^,]*,\s*/i,'').trim(); if(t) title=t; }
      else if(l&&!l.startsWith('#')){ add(l,title); title=''; } }); }
  if(out.length>0) return out; if(/^https?:\/\//i.test(b)) return [{title:'频道 1',url:b}]; return [];
}
async function resolveStreams(url,depth,headers){ depth=depth||0; if(depth>3) return [{title:'频道 1',url}];
  try{ const r=await Promise.resolve(reader.http.fetch({url,method:'GET',headers:Object.assign({'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'},headers||{}),timeoutMs:15000}));
    if(r&&Number(r.status||0)>=200&&Number(r.status||0)<400){ const ct=contentTypeOf(r); const body=text(r.body||'');
      if(/audio\//i.test(ct)&&!/pls|mpegurl|playlist/i.test(ct)) return [{title:'频道 1',url}];
      if(/mpegurl|playlist/i.test(ct)||/^\[playlist\]|#EXTM3U|#EXTINF/i.test(body.trim())){
        const parsed=parsePlaylist(body,url,depth); if(parsed.length) return parsed; }
      if(/^https?:\/\//i.test(url)) return [{title:'频道 1',url}]; }
  }catch(_){}
  return [{title:'频道 1',url}];
}
function cacheKey(url){ return 'radio.cache.'+encodeURIComponent(text(url)); }
async function resolveStationChannels(st){
  if(st && text(st.content).trim()){ const body=text(st.content).replace(/^\uFEFF/,'').trim();
    let list=[]; try{ list=parsePlaylist(body, st.url||''); }catch(_){}
    return list&&list.length?list:[{title:'频道 1',url:st.url||''}]; }
  try{ const l=await resolveStreamsCached(st && st.url, st && st.headers); return l&&l.length?l:[{title:'频道 1',url:st && st.url}]; }catch(_){ return [{title:'频道 1',url:st && st.url}]; }
}
async function resolveStreamsCached(url,headers){
  try{ const c=await Promise.resolve(reader.storage.get(cacheKey(url)));
    if(c&&typeof c==='object'&&Array.isArray(c.list)&&c.list.length&&(Date.now()-Number(c.at||0))<600000) return c.list; }catch(_){}
  const list=await resolveStreams(url,0,headers);
  try{ await Promise.resolve(reader.storage.set(cacheKey(url),{list,at:Date.now()})); }catch(_){}
  return list;
}
function stationHeaders(st){ return Object.assign({'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Referer':(text(st.url).match(/^https?:\/\/[^/]+/)||[''])[0]}, hdrs(st.headers)); }
function channelKey(url){ return 'radio.ch.'+encodeURIComponent(text(url)); }
function urlFromChannelKey(k){ return decodeURIComponent(text(k).replace(/^radio\.ch\./,'')); }
function channelBook(ch,st){ return { bookKey:channelKey(ch.url), title:ch.title||'电台', author:(st&&st.group)||'广播电台',
  intro:ch.url, bookUrl:ch.url, tocUrl:ch.url, sourceName:'广播电台', mediaType:'audiobook' }; }
async function allChannels(){
  const out=[]; const sts=await getStationsAsync();
  for(const st of sts){ let list=await resolveStationChannels(st);
    if(!list.length) list=[{title:'频道 1',url:st.url}];
    list.forEach((ch,i)=>{ const isNamed = ch.title && ch.title.indexOf('频道')!==0; const t = isNamed ? ch.title : (list.length>1 ? (st.name+' · '+(i+1)) : st.name); out.push({ ...channelBook({title:t,url:ch.url},st), _st:st, _url:ch.url }); }); }
  return out;
}
module.exports.search=async function({keyword,page}){ const kw=text(keyword).trim().toLowerCase(); const list=await allChannels();
  const r=list.filter(x=>!kw||x.title.toLowerCase().indexOf(kw)>=0||x.intro.toLowerCase().indexOf(kw)>=0);
  return r.slice(0,500).map(x=>{ const c={bookKey:x.bookKey,title:x.title,author:x.author,intro:x.intro,bookUrl:x.bookUrl,tocUrl:x.tocUrl,sourceName:'广播电台',mediaType:'audiobook'}; return c; }); };
module.exports.detail=async function({bookKey}){ const url=urlFromChannelKey(bookKey);
  const f=text(url).split('/').pop().replace(/[?#].*$/,''); const title=f||'广播电台';
  return { bookKey, title, author:'广播电台', intro:url, bookUrl:url, tocUrl:url, sourceName:'广播电台', mediaType:'audiobook' }; };
module.exports.catalog=async function({bookKey}){ const url=urlFromChannelKey(bookKey);
  return [{ chapterKey:channelKey(url), title:'收听直播', ordinal:0, chapterUrl:url, isVolume:false, isLocked:false, mediaType:'audiobook' }]; };
module.exports.content=async function({chapterUrl,bookKey}){
  const url=text(chapterUrl).trim(); if(!/^https?:\/\//i.test(url)) throw new Error('电台流地址无效');
  const sts=await getStationsAsync(); let st=null;
  for(const s of sts){ try{ const l=await resolveStationChannels(s); if(l.some(c=>text(c.url)===url)){ st=s; break; } }catch(_){} }
  if(!st) st={url,headers:{}};
  let play=url; try{ const l=await resolveStreamsCached(url,st.headers); if(l&&l.length) play=l[0].url; }catch(_){}
  const probe=await probeStream(play,st.headers,6000);
  return { contentType:'audio', content:'', mediaUrl:play, mediaUrls:[play], mediaHeaders:stationHeaders(st), title:'', baseUrl:url,
    message:probe.ok?'':('该频道流当前暂不可访问（'+(probe.msg||'')+'），可换一个频道或检查网络/授权') };
};
module.exports.exploreMenu=async function(){ const list=await getStationsAsync(); const groups=[];
  list.forEach(s=>{ if(s.group&&groups.indexOf(s.group)<0) groups.push(s.group); });
  const items=[{key:'all',title:'全部电台'}]; groups.forEach(g=>items.push({key:g,title:g})); return items; };
module.exports.explore=async function({category,page}){ const cat=text(category); const list=await allChannels();
  const r=(!cat||cat==='all'||cat==='全部')?list:list.filter(x=>x.author===cat);
  const pageSize=40, p=Math.max(1,Number(page||1)); const slice=r.slice((p-1)*pageSize,p*pageSize);
  return slice.map(x=>({bookKey:x.bookKey,title:x.title,author:x.author,intro:x.intro,bookUrl:x.bookUrl,tocUrl:x.tocUrl,sourceName:'广播电台',mediaType:'audiobook'})); };
module.exports.manage=async function(input){ const action=input&&input.action;
  if(action==='parseText'){ const body=text(input&&input.text||'').replace(/^\uFEFF/,'').trim();
    if(!body) throw new Error('请粘贴 m3u/pls/xml/rss 内容');
    let streams=[]; try{ streams=parsePlaylist(body, input&&input.base||''); }catch(_){}
    if(!streams.length) throw new Error('未能从文本解析出频道');
    const domains=[]; const seen=new Set(); streams.forEach(s=>{ const m=String(s.url).match(/^https?:\/\/([^/?#]+)/i); if(m){ const d=m[1].toLowerCase().replace(/\.$/,''); if(d&&!seen.has(d)){ seen.add(d); domains.push(d); } } });
    const preview=[]; const lim=Math.min(streams.length,30), bt=8;
    for(let i=0;i<lim;i+=bt){ const seg=streams.slice(i,i+bt); const rs=await Promise.all(seg.map(s=>probeStream(s.url,{},5000))); rs.forEach((r,j)=>preview.push({title:(seg[j].title||'频道 '+(i+j+1)),url:seg[j].url,ok:r.ok})); }
    return { type:streams.length>1?'playlist':'single', channels:streams.length, preview, domains, streams }; }
  if(action==='probeDomains'){ const url=text(input&&input.url).trim(); if(!/^https?:\/\/\S+$/i.test(url)) return {domains:[],channels:0};
    let streams=[]; try{ streams=await resolveStreamsCached(url,hdrs(input&&input.headers)); }catch(_){}
    const domains=[]; const seen=new Set();
    [url].concat(streams.map(s=>s.url)).forEach(u=>{ const m=String(u).match(/^https?:\/\/([^/?#]+)/i); if(m){ const d=m[1].toLowerCase().replace(/\.$/,''); if(d&&!seen.has(d)){ seen.add(d); domains.push(d); } } });
    return {domains,channels:streams.length}; }
  if(action==='probeStation'){ const url=text(input&&input.url).trim(); if(!/^https?:\/\/\S+$/i.test(url)) throw new Error('请输入有效地址');
    let streams=[]; try{ streams=await resolveStreamsCached(url,hdrs(input&&input.headers)); }catch(_){}
    if(!streams.length) throw new Error('无法解析该源');
    const p=await probeStream(streams[0].url, hdrs(input&&input.headers),6000); if(!p.ok) throw new Error('首个频道暂不可访问：'+(p.msg||''));
    const domains=[]; const seen=new Set(); [url].concat(streams.map(s=>s.url)).forEach(u=>{ const m=String(u).match(/^https?:\/\/([^/?#]+)/i); if(m){ const d=m[1].toLowerCase().replace(/\.$/,''); if(d&&!seen.has(d)){ seen.add(d); domains.push(d); } } });
    return {valid:true,domains,channels:streams.length}; }
  if(action==='importUrl'){ const url=text(input&&input.url).trim(); if(!/^https?:\/\/\S+$/i.test(url)) throw new Error('请输入有效地址');
    let streams=[]; try{ streams=await resolveStreamsCached(url,{}); }catch(_){}
    if(!streams.length) throw new Error('无法解析该链接');
    const domains=[]; const seen=new Set(); [url].concat(streams.map(s=>s.url)).forEach(u=>{ const m=String(u).match(/^https?:\/\/([^/?#]+)/i); if(m){ const d=m[1].toLowerCase().replace(/\.$/,''); if(d&&!seen.has(d)){ seen.add(d); domains.push(d); } } });
    const preview=[]; const lim=Math.min(streams.length,30), bt=8;
    for(let i=0;i<lim;i+=bt){ const seg=streams.slice(i,i+bt); const rs=await Promise.all(seg.map(s=>probeStream(s.url,{},5000)));
      rs.forEach((r,j)=>preview.push({title:(seg[j].title||'频道 '+(i+j+1)),url:seg[j].url,ok:r.ok})); }
    return { type:streams.length>1?'playlist':'single', channels:streams.length, preview, domains }; }
  return { schemaVersion:1 }; };
module.exports.ui=async function(){ return { schemaVersion:1 }; };
